def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',type=Path,default=Path(os.environ.get('SP2PORT',str(Path.home()/'sp2port'))));p.add_argument('--restore',action='store_true');p.add_argument('--check',action='store_true');a=p.parse_args()
 path=a.root/'runtime/src/nvn/nvn_vk.cpp';data=path.read_bytes();states=[]
 for old,new in CHANGES:
  choices=[]
  for nl in (b'\n',b'\r\n'):
   oldb=old.replace('\r\n','\n').encode().replace(b'\n',nl);newb=new.encode().replace(b'\n',nl)
   if data.count(newb)==1:choices.append((newb,oldb if a.restore else newb,True))
  if not choices:
   for nl in (b'\n',b'\r\n'):
    oldb=old.replace('\r\n','\n').encode().replace(b'\n',nl);newb=new.encode().replace(b'\n',nl)
    if data.count(oldb)!=1:continue
    if b'\n' not in oldb:
     at=data.index(oldb)+len(oldb);local=b'\r\n' if data[at:at+2]==b'\r\n' else b'\n'
     if nl!=local:continue
    choices.append((oldb,oldb if a.restore else newb,False))
  choices=list(dict.fromkeys(choices))
  if len(choices)!=1:raise SystemExit('Recent capture source mismatch; no files changed')
  before,after,state=choices[0];states.append(state);data=data.replace(before,after,1)
 if len(set(states))!=1:raise SystemExit('Partial recent capture patch; no files changed')
 if a.check:print('Preflight passed');return
 path.write_bytes(data);print('Restored' if a.restore else 'Applied; rebuild nvn_vk.cpp')
if __name__=='__main__':main()
